// utils.js (ESM)
export function add(a, b) { return a + b; }
export function subtract(a, b) { return a - b; }
export function multiply(a, b) { return a * b; }
export function divide(a, b) { return a / b; }

// main.js
import { add, multiply } from './utils.js';

console.log(add(2, 3));
console.log(multiply(4, 5));

Build Process:
1. Bundler analyzes imports in main.js
2. Identifies that add and multiply are used
3. Identifies that subtract and divide are never imported
4. Marks subtract and divide as dead code
5. Removes unused exports from final bundle

Result:
- Bundle only contains add and multiply functions
- subtract and divide are completely removed
- Bundle size reduced by ~50%

// ESM (tree-shakeable)
export function usedFunction() { return 'used'; }
export function unusedFunction() { return 'unused'; }

import { usedFunction } from './module.js';
// unusedFunction can be removed

// CommonJS (not tree-shakeable)
function usedFunction() { return 'used'; }
function unusedFunction() { return 'unused'; }

module.exports = {
  usedFunction,
  unusedFunction
};

const { usedFunction } = require('./module.js');
// Both functions are included - can't determine usage at build time

module.exports = {
  mode: 'production', // Enables built-in optimizations

  optimization: {
    usedExports: true, // Mark unused exports
    sideEffects: false, // Assume modules have no side effects
    minimize: true, // Enable minification
  },

  // Or specify sideEffects in package.json
  // "sideEffects": false
};

// Good: Tree-shakeable library
// utils.js
export function add(a, b) { return a + b; }
export function subtract(a, b) { return a - b; }
export function multiply(a, b) { return a * b; }
export function divide(a, b) { return a / b; }

// main.js (entry point)
export * from './utils.js';

// Consumer can import only what they need
import { add, multiply } from 'my-library';
// subtract and divide are tree-shaken

// Bad: Not tree-shakeable
// utils.js
const utils = {
  add: (a, b) => a + b,
  subtract: (a, b) => a - b,
  multiply: (a, b) => a * b,
  divide: (a, b) => a / b
};

export default utils;

// Consumer gets everything even if they only use add
import utils from 'my-library';
// All functions included in bundle

const BundleAnalyzerPlugin = require('webpack-bundle-analyzer').BundleAnalyzerPlugin;

module.exports = {
  plugins: [
    new BundleAnalyzerPlugin({
      analyzerMode: 'static',
      openAnalyzer: false,
      reportFilename: 'bundle-report.html'
    })
  ]
};

// Run: npm run build
// Open: bundle-report.html
// Check:
// - Are unused functions still in the bundle?
