// Better: Standalone functions (easily tree-shaken)
export function formatDate(date) { /* ... */ }
export function parseDate(string) { /* ... */ }
export function validateDate(date) { /* ... */ }

// Consumer imports only what they need
import { formatDate } from './date-utils';
// parseDate and validateDate are removed

// Harder: Class methods (harder to tree-shake)
export class DateUtils {
  static formatDate(date) { /* ... */ }
  static parseDate(string) { /* ... */ }
  static validateDate(date) { /* ... */ }
}

// Consumer
import { DateUtils } from './date-utils';
// All methods included (harder to eliminate unused ones)

// lib.js
export const utils = {
  add: (a, b) => a + b,
  subtract: (a, b) => a - b,
  multiply: (a, b) => a * b,
  divide: (a, b) => a / b
};

// main.js
import { utils } from './lib.js';
const result = utils.add(2, 3);

// With webpack's property access tree shaking:
// Only add function is included in bundle
// subtract, multiply, divide are removed

